export class JitterBackoff {
  // Full Jitter: Uniformly random between 0 and exponential ceiling
  static fullJitter(attempt: number, baseMs = 100, capMs = 5000): number {
    const exponentialCeiling = Math.min(capMs, baseMs * Math.pow(2, attempt));
    return Math.floor(Math.random() * exponentialCeiling);
  }

  // Equal Jitter: Half deterministic backoff, half randomized jitter
  static equalJitter(attempt: number, baseMs = 100, capMs = 5000): number {
    const ceiling = Math.min(capMs, baseMs * Math.pow(2, attempt));
    const half = Math.floor(ceiling / 2);
    return half + Math.floor(Math.random() * half);
  }
}
